example.code:
function siftDown(a, i, n) {
  while (true) {
    let s = i
    const l = 2 * i + 1
    const r = 2 * i + 2
    if (l <= n - 1 && a[s] > a[l]) s = l
    if (r <= n - 1 && a[s] > a[r]) s = r
    if (s === i) return
    const t = a[i]; a[i] = a[s]; a[s] = t
    i = s
  }
}

